      font.missingFile &&
      !font.systemFontInfo &&
      !isType3Font &&
      this.options.useSystemFonts
    ) {
      const standardFontName = getStandardFontName(fontName.name);
      const substitution = getFontSubstitution(
        this.systemFontCache,
        this.idFactory,
